class Main {
    static class Box {
        // 같은 객체를 가리키면 같은 value를 읽어요.
        int value;
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Box a = new Box();
        a.value = n;
        // 새 객체 대신 같은 참조를 전달해요.
        Box b = new Box();
        b.value += 2;
        System.out.println(a.value);
    }
}
